// Dipicu jadwal kuartalan 02:00 WIB (1 Jan / Apr / Jul / Okt)
// -> hanya job bergroup "kuartalan".
return [{ json: { group: 'kuartalan', dry_run: false } }];

// ====================================================================
// TRIGGER MANUAL -- DEFAULT DRY RUN
// --------------------------------------------------------------------
// Berbeda dari "Test manual" di DASH_AUDIT Cleanup lama, yang langsung
// menghapus data produksi. Di sini trigger manual default-nya HANYA
// menghitung dan melaporkan; sheet tidak disentuh.
//
// Mau benar-benar menghapus lewat trigger manual? Ubah satu baris di
// bawah jadi false, jalankan, lalu kembalikan ke true.
// ====================================================================
const MANUAL_DRY_RUN = true;

return [{ json: { group: 'semua', dry_run: MANUAL_DRY_RUN } }];

// ====================================================================
// KONFIGURASI  --  HANYA NODE INI YANG PERLU DIEDIT
// --------------------------------------------------------------------
// Menggantikan 3 workflow:
//   - VIRA - MSG_BUFFER Cleanup (harian 03:00 WIB)
//   - VIRA-PCR - MSG_BUFFER Cleanup (harian 03:00 WIB)
//   - VIRA Dashboard - DASH_AUDIT Cleanup (tiap 3 bulan, 02:00 WIB)
//
// Tambah klien ke-3 = tambah 2 baris di JOBS (1 harian + 1 kuartalan).
// Tambah jenis pembersihan baru = tambah 1 baris. Node lain tidak disentuh.
//
// Field per job:
//   group          'harian' | 'kuartalan'  -> jadwal mana yang memicunya
//   doc_id         id spreadsheet
//   tab            nama tab
//   ts_col         nama kolom timestamp yang dipakai menilai umur baris
//   mode           'epoch_ms' -> kolom ts berisi angka epoch milidetik
//                  'iso'      -> kolom ts berisi tanggal yang bisa di-Date.parse
//   ttl_ms         (mode epoch_ms) umur maksimum baris, dalam milidetik
//   retention_days (mode iso) umur maksimum baris, dalam hari.
//                  0 atau kurang = WIPE semua baris data, header tetap aman
//   on_bad_ts      'stop'   -> ts tidak terbaca => berhenti, jangan hapus lebih jauh
//                  'delete' -> ts tidak terbaca => anggap sampah lama, ikut dihapus
//
// CATATAN: semua job memakai satu credential Google
// ("Google Service Account - VIRA Dashboard") yang sudah terbukti bisa
// membuka kedua spreadsheet. Job baru untuk spreadsheet lain harus
// memastikan service account itu sudah di-share ke sheet tersebut.
// ====================================================================

const DOC_TS  = '1tEJYayS0pQTVO2FI9xO363nQBkjFz5TL5u0-zsa-CwE'; // The_Scholars_Database
const DOC_PCR = '1pzGuRZbDXCFSZrHHbiEpTbF8F-_yMY0yex80_NmjB4o'; // PCR_Database
const DOC_VP  = '1C5gF1TTJFAHCrfVESiaIhAts6iByRH9BRjLqBCO_Yxk'; // VIRA Steven Database (VIRA Personal)

const DUA_JAM_MS = 2 * 60 * 60 * 1000;

const JOBS = [
  // ---------- harian 03:00 WIB : buang buffer pesan yang sudah lewat 2 jam ----------
  // RETENTION harus > MAX_AGE_MS (30 mnt) di node "Cek_user_status" pada
  // workflow bot utama. Baris > 30 mnt tidak pernah dipakai untuk merge,
  // jadi 2 jam aman.
  { group: 'harian', tenant: 'thescholars', nama: 'The Scholars',
    doc_id: DOC_TS,  tab: 'MSG_BUFFER', ts_col: 'ts',
    mode: 'epoch_ms', ttl_ms: DUA_JAM_MS, on_bad_ts: 'stop' },

  { group: 'harian', tenant: 'persada', nama: 'Persada Cisoka Residence',
    doc_id: DOC_PCR, tab: 'MSG_BUFFER', ts_col: 'ts',
    mode: 'epoch_ms', ttl_ms: DUA_JAM_MS, on_bad_ts: 'stop' },

  // 2026-08-28: tenant ke-3. Menggantikan workflow terpisah
  // "VIRA Personal - MSG_BUFFER Cleanup" yang karena itu TIDAK perlu dideploy.
  // Prasyarat: service account "Google Service Account - VIRA Dashboard" sudah
  // di-share sebagai Editor ke spreadsheet VIRA Steven Database.
  { group: 'harian', tenant: 'personal', nama: 'VIRA Personal (Steven)',
    doc_id: DOC_VP,  tab: 'MSG_BUFFER', ts_col: 'ts',
    mode: 'epoch_ms', ttl_ms: DUA_JAM_MS, on_bad_ts: 'stop' },

  // ---------- kuartalan 02:00 WIB : bersihkan log audit dashboard ----------
  // retention_days 0 = wipe penuh (perilaku yang berjalan sekarang).
  // Ganti ke 90 kalau mau menyimpan jejak audit 90 hari terakhir.
  { group: 'kuartalan', tenant: 'thescholars', nama: 'The Scholars',
    doc_id: DOC_TS,  tab: 'DASH_AUDIT', ts_col: 'ts',
    mode: 'iso', retention_days: 0, on_bad_ts: 'delete' },

  { group: 'kuartalan', tenant: 'persada', nama: 'Persada Cisoka Residence',
    doc_id: DOC_PCR, tab: 'DASH_AUDIT', ts_col: 'ts',
    mode: 'iso', retention_days: 0, on_bad_ts: 'delete' },

  // 2026-08-28: DASH_AUDIT tenant ke-3 (VIRA Personal).
  // Wipe total tiap kuartal, header dipertahankan -- sama seperti 2 tenant lain.
  { group: 'kuartalan', tenant: 'personal', nama: 'VIRA Personal (Steven)',
    doc_id: DOC_VP,  tab: 'DASH_AUDIT', ts_col: 'ts',
    mode: 'iso', retention_days: 0, on_bad_ts: 'delete' },
];

// --------------------------------------------------------------------
const ctl    = $input.first().json || {};
const group  = String(ctl.group || 'semua');
const dryRun = ctl.dry_run === true;

const dipilih = JOBS.filter(j => group === 'semua' || j.group === group);

if (!dipilih.length) {
  console.warn('Tidak ada job untuk group "' + group + '".');
  return [];
}

console.log('Menjalankan ' + dipilih.length + ' job (group=' + group + ', dry_run=' + dryRun + ').');

// Satu item per job -> diproses satu-satu oleh "Loop Over Jobs".
return dipilih.map(j => ({ json: { ...j, dry_run: dryRun } }));

// ====================================================================
// PLAN DELETE  (1 job per iterasi)
// --------------------------------------------------------------------
// Baris terlama selalu berada di blok kontigu paling atas, karena kedua
// tab yang ditangani (MSG_BUFFER, DASH_AUDIT) ditulis append-only. Jadi
// cukup 1x delete range per job -> hemat kuota tulis Google Sheets.
//
// Header (baris 1) TIDAK PERNAH ikut: filter row_number >= 2.
// Kalau tab belum dibuat, node "Read Tab" di-set onError=continueRegularOutput
// sehingga item yang masuk ke sini tidak punya row_number -> tersaring jadi
// 0 baris -> job dilewati, bukan error.
// ====================================================================
const ctx = $('Loop Over Jobs').first().json;

const base = {
  group:   ctx.group,
  tenant:  ctx.tenant,
  nama:    ctx.nama,
  doc_id:  ctx.doc_id,
  tab:     ctx.tab,
  dry_run: ctx.dry_run === true,
};

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.row_number !== undefined && Number(r.row_number) >= 2)
  .sort((a, b) => Number(a.row_number) - Number(b.row_number)); // atas -> bawah

if (!rows.length) {
  return [{ json: { ...base, startRow: 0, count: 0,
                    alasan: 'tidak ada baris data (tab kosong / belum dibuat)' } }];
}

const startRow = Number(rows[0].row_number); // normalnya 2
const tsCol    = ctx.ts_col || 'ts';
const mode     = ctx.mode === 'epoch_ms' ? 'epoch_ms' : 'iso';
const retDays  = Number(ctx.retention_days || 0);

// Wipe penuh: hanya berlaku untuk mode iso dengan retention_days <= 0.
if (mode === 'iso' && retDays <= 0) {
  return [{ json: { ...base, startRow, count: rows.length,
                    alasan: 'wipe penuh, header dipertahankan' } }];
}

const cutoff = mode === 'epoch_ms'
  ? Date.now() - Number(ctx.ttl_ms || 0)
  : Date.now() - retDays * 24 * 60 * 60 * 1000;

// Hitung run kontigu baris kadaluarsa mulai dari baris teratas.
let n = 0;
for (const r of rows) {
  const raw   = r[tsCol];
  const t     = mode === 'epoch_ms' ? Number(raw) : Date.parse(raw);
  const valid = Number.isFinite(t) && t > 0;

  if (valid && t < cutoff) { n++; continue; }          // kadaluarsa -> hapus
  if (!valid && ctx.on_bad_ts === 'delete') { n++; continue; } // ts rusak dianggap sampah lama

  if (!valid) {
    console.warn('Baris ' + r.row_number + ' di ' + ctx.tab + ' (' + ctx.tenant + ') ts tidak valid ("' + raw + '") - stop, tidak hapus lebih jauh.');
  }
  break;                                               // masih segar / ts rusak & on_bad_ts=stop
}

const alasan = mode === 'epoch_ms'
  ? 'ttl ' + Math.round(Number(ctx.ttl_ms || 0) / 60000) + ' menit'
  : 'retensi ' + retDays + ' hari';

return [{ json: { ...base, startRow, count: n, alasan } }];

// Node googleSheets "delete" membuang konteks di output-nya.
// Ambil lagi dari node Plan supaya ringkasan akhir tetap informatif.
const ctx = $('Plan Delete').first().json;
return [{ json: { ...ctx, status: 'deleted' } }];

const ctx = $('Plan Delete').first().json;
// Bedakan "memang tidak ada yang perlu dihapus" dari "dry run menahan penghapusan".
const status = (ctx.dry_run === true && Number(ctx.count || 0) > 0) ? 'dry_run' : 'skipped';
return [{ json: { ...ctx, status } }];

// Output SplitInBatches cabang "done" = semua item yang kembali ke loop.
const detail = $input.all().map(i => i.json).map(r => ({
  group:       r.group || '?',
  tenant:      r.tenant || '?',
  tab:         r.tab || '?',
  status:      r.status || 'unknown',
  mulai_baris: Number(r.startRow || 0),
  dihapus:     Number(r.count || 0),
  alasan:      r.alasan || '',
  dry_run:     r.dry_run === true,
}));

const dryRun     = detail.some(d => d.dry_run);
const terhapus   = detail.filter(d => d.status === 'deleted').reduce((a, b) => a + b.dihapus, 0);
const akanHapus  = detail.filter(d => d.status === 'dry_run').reduce((a, b) => a + b.dihapus, 0);

// Job harian jalan tiap hari -> sengaja TIDAK dinotifikasi supaya tidak jadi spam.
// Kegagalannya tetap tertangkap lewat Error Workflow.
// Job kuartalan (destruktif) dan semua dry run selalu dilaporkan.
const notify = detail.some(d => d.group !== 'harian') || dryRun;

const lines = [];
lines.push('\u{1F9F9} [VIRA] SHEET CLEANUP');
if (dryRun) lines.push('*** DRY RUN - sheet TIDAK disentuh ***');
lines.push('');
for (const d of detail) {
  lines.push('- ' + d.tenant + ' / ' + d.tab + ' : ' + d.status
    + (d.dihapus ? ' ' + d.dihapus + ' baris (mulai ' + d.mulai_baris + ')' : ' 0 baris')
    + ' [' + d.alasan + ']');
}
lines.push('');
lines.push(dryRun ? ('AKAN dihapus : ' + akanHapus + ' baris')
                  : ('Dihapus      : ' + terhapus + ' baris'));

return [{ json: {
  ok: true,
  workflow: 'GLOBAL - Sheet Cleanup',
  dry_run: dryRun,
  total_baris_dihapus: terhapus,
  total_baris_akan_dihapus: akanHapus,
  notify,
  report: lines.join('\n'),
  detail,
} }];
